net=model.load()
th=lambda c: -179.6+67*c
def off(a,c):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); return ((ang-th(c)+180)%360-180)
W=torch.tensor(np.load('det_10_13.npy')); B=float(np.load('detb_10_13.npy')[0])
J=torch.tensor([[0.,-1.],[1.,0.]])
def mk(seed,N):
    rng=np.random.default_rng(seed)
    return torch.tensor(rng.standard_normal((N,2)).astype(np.float32)), torch.tensor(rng.random(N).astype(np.float32))
@torch.no_grad()
def run(xi,c,mode,kappa=8,M=None,collect=False):
    N=len(xi); x=xi.clone(); H=[];X=[];G=[]
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,A=net.velocity(x,t,c,("blocks.2",),count=False)
        h=A["blocks.2"]
        if 10<=k<13:
            g=(h@W+B)>0
            if collect: H.append(h[g]);X.append(x[g]);G.append(torch.nonzero(g)[:,0])
            if mode=='rot': v=v+g[:,None].float()*(-kappa*(x@J.T))
            if mode=='lin': v=v+g[:,None].float()*(h@M[0].T+M[1])
        x=x-v/20
    return x.numpy(),(H,X,G)
def hist(o):
    bins=np.round(o/45).astype(int)%8; return np.bincount(bins,minlength=8)/len(o)
