a0,(H,X,G)=run(xi,c,'none',collect=True)
o0=off(a0,c.numpy()); s=np.sign(o0)
Hh=torch.cat(H);Xx=torch.cat(X);Gg=torch.cat(G).numpy()
for kappa in [8,10]:
    Y=-kappa*torch.tensor(s[Gg],dtype=torch.float32)[:,None]*(Xx@J.T)
    Ha=torch.cat([Hh,torch.ones(len(Hh),1)],1)
    sol=torch.linalg.solve(Ha.T@Ha+1.0*torch.eye(129),Ha.T@Y)
    pred=Ha@sol; print('R2',1-((pred-Y)**2).sum()/((Y-Y.mean(0))**2).sum())
    M=(sol[:128].T.contiguous(),sol[128])
    xt,ct=mk(7,12000)
